    _ = @"query_#/components/parameters/repo";
    _ = @"query_#/components/parameters/issue-number";

    var client = std.http.Client { .allocator = allocator };
    defer client.deinit();

    const headers = &[_]std.http.Header{
        .{ .name = "Content-Type", .value = "application/json" },
        .{ .name = "Accept", .value = "application/json" },
    };

    const uri_str = try std.fmt.allocPrint(allocator, "/repos/{owner}/{repo}/issues/{issue_number}", .{});
    defer allocator.free(uri_str);
    const uri = try std.Uri.parse(uri_str);
    var req = try client.request(std.http.Method.GET, uri, .{ .extra_headers = headers });
    defer req.deinit();

    try req.sendBodiless();

    var response = try req.receiveHead(&.{});
    if (response.head.status != .ok) {
        return error.ResponseError;
    }

    var reader_buffer: [100]u8 = undefined;
    const body_reader = response.reader(&reader_buffer);
    const body = try body_reader.readAlloc(allocator, response.head.content_length orelse 1024 * 1024 * 4);
    defer allocator.free(body);

    const parsed = try std.json.parseFromSlice(issue, allocator, body, .{});
    defer parsed.deinit();

    return parsed.value;
}

